<?php
declare(strict_types=1);
final class NextWorkSnapshotBuilder{
 private const LIMITS=['project_context'=>20,'steps'=>20,'executions'=>10,'events'=>20,'artifacts'=>15,'recent_tasks'=>10];
 public function __construct(private NextWorkSnapshotSourceInterface$source){}
 public function build(int$userId,int$projectId,string$taskPublicId):NextWorkSnapshot{if($userId<1||$projectId<1||!TaskPublicId::isValid($taskPublicId))throw new TaskValidationException('next_work_scope_invalid');$raw=$this->source->load($userId,$projectId,$taskPublicId);$project=$raw['project']??null;$task=$raw['task']??null;if(!is_array($project))throw new TaskNotFoundException('project_not_found');if(!is_array($task))throw new TaskNotFoundException('task_not_found');if((int)($project['user_id_']??0)!==$userId)throw new TaskNotFoundException('project_not_found');if((int)($task['user_id_']??0)!==$userId||(int)($task['project_id_']??0)!==$projectId||(string)($task['public_id']??'')!==$taskPublicId)throw new TaskNotFoundException('task_not_found');$status=(string)($task['status']??'');if(!in_array($status,['completed','failed','cancelled'],true))throw new TaskTransitionException('next_work_task_not_terminal');$data=['project'=>['name'=>$this->text($project['name']??'',255),'description'=>$this->text($project['description']??'',2000),'status'=>$this->text($project['status']??'',32)],'project_context'=>$this->items($raw['project_context']??[],'project_context',fn($r)=>['type'=>$this->text($r['type']??'',20),'title'=>$this->text($r['title']??'',255),'content'=>$this->text($r['content']??'',1000)]),'task'=>['public_id'=>$taskPublicId,'title'=>$this->text($task['title']??'',255),'objective'=>$this->text($task['objective']??'',2000),'status'=>$status,'result_summary'=>$this->text($task['result_summary']??'',1500),'error_summary'=>$this->text($task['error_message']??'',600)],'steps'=>$this->items($raw['steps']??[],'steps',fn($r)=>['step_key'=>$this->key($r['step_key']??''),'title'=>$this->text($r['title']??'',255),'step_type'=>$this->text($r['step_type']??'',32),'status'=>$this->text($r['status']??'',32),'output_summary'=>$this->text($r['output_summary']??'',800),'agent_key'=>$this->key($r['agent_key']??'')]),'executions'=>$this->items($raw['executions']??[],'executions',fn($r)=>['attempt_number'=>(int)($r['attempt_number']??0),'step_key'=>$this->key($r['step_key']??''),'status'=>$this->text($r['status']??'',32),'model_id'=>$this->text($r['model_id']??'',255),'error_summary'=>$this->text($r['error_message']??'',400)]),'events'=>$this->items($raw['events']??[],'events',fn($r)=>['event_key'=>$this->key($r['event_key']??''),'from_status'=>$this->text($r['from_status']??'',32),'to_status'=>$this->text($r['to_status']??'',32),'summary'=>$this->text($r['summary']??'',400)]),'artifacts'=>$this->items($raw['artifacts']??[],'artifacts',fn($r)=>['relation'=>$this->text($r['relation']??'',20),'resource_type'=>$this->text($r['resource_type']??'',40),'public_metadata'=>$this->text($r['public_metadata']??'',300)]),'recent_tasks'=>$this->items($raw['recent_tasks']??[],'recent_tasks',fn($r)=>['public_id'=>$this->text($r['public_id']??'',100),'title'=>$this->text($r['title']??'',255),'status'=>$this->text($r['status']??'',32),'result_summary'=>$this->text($r['result_summary']??'',500)])];$this->boundTotal($data);$refs=['project',$taskPublicId];foreach($data['project_context']as$i=>$x)$refs[]='project_context:'.($i+1);foreach($data['steps']as$x)if($x['step_key']!=='')$refs[]='step:'.$x['step_key'];foreach($data['executions']as$i=>$x)$refs[]='execution:'.($i+1);foreach($data['events']as$i=>$x)$refs[]='event:'.($i+1);foreach($data['artifacts']as$i=>$x)$refs[]='artifact:'.($i+1);foreach($data['recent_tasks']as$x)if($x['public_id']!=='')$refs[]=$x['public_id'];$goal=trim($data['project']['description'])!=='';foreach($data['project_context']as$x)if(in_array($x['type'],['rule','decision','todo'],true)&&trim($x['content'])!=='')$goal=true;return new NextWorkSnapshot($data,array_values(array_unique($refs)),$goal);}
 private function items(mixed$rows,string$key,callable$map):array{if(!is_array($rows))return[];$rows=array_slice(array_values($rows),0,self::LIMITS[$key]);return array_map($map,$rows);}
 private function text(mixed$value,int$max):string{if(!is_scalar($value))return'';$text=trim(preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u','',(string)$value)??'');$text=preg_replace('/\b(password|token|secret|api[_-]?key)\s*[:=]\s*\S+/iu','$1=[REDACTED]',$text)??$text;return mb_substr($text,0,$max);}
 private function boundTotal(array&$data):void{foreach(['recent_tasks','events','executions','artifacts','project_context','steps']as$key){while($data[$key]!==[]&&strlen(json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))>NextWorkSnapshot::MAX_TOTAL_BYTES)array_pop($data[$key]);}}
 private function key(mixed$value):string{$key=$this->text($value,100);return preg_match('/^[a-z][a-z0-9_:-]{0,99}$/D',$key)?$key:'';}
}
